Self-contained test case:

``` java
import io.netty.bootstrap.Bootstrap;
import io.netty.bootstrap.ServerBootstrap;
import io.netty.buffer.ByteBuf;
import io.netty.channel.ChannelFuture;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelInitializer;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.socket.SocketChannel;
import io.netty.channel.socket.nio.NioServerSocketChannel;
import io.netty.channel.socket.nio.NioSocketChannel;
import io.netty.handler.codec.ByteToMessageCodec;
import io.netty.handler.logging.LogLevel;
import io.netty.handler.logging.LoggingHandler;

public class DecoderExceptionTest {

    public static void main(String[] args) throws Exception {
        new DecoderExceptionTest();
    }

    public DecoderExceptionTest() throws Exception {
        new Server().start();
        Thread.sleep(1000);
        new Client().start();
    }

    private static class Client implements Runnable {
        public void start() {
            new Thread(this).start();
        }

        @Override
        public void run() {
            try {
                Bootstrap b = new Bootstrap();
                try {
                    b.group(new NioEventLoopGroup())
                     .channel(NioSocketChannel.class)
                     .handler(new ChannelInitializer<SocketChannel>() {
                         @Override
                         protected void initChannel(SocketChannel socketChannel) throws Exception {
                             socketChannel.pipeline().addLast(new LoggingHandler(LogLevel.INFO));
                             socketChannel.pipeline().addLast(new IntegerCodec());
                         }
                     });

                    ChannelFuture f = b.connect("localhost", 0xAF12).sync();
                    f.channel().write(1);
                } finally {
                    b.shutdown();
                }
            } catch (Exception e) {
                System.err.println(e);
            }
        }
    }

    private static class Server implements Runnable {
        public void start() {
            new Thread(this).start();
        }

        @Override
        public void run() {
            ServerBootstrap b = new ServerBootstrap();
            try {
                b.group(new NioEventLoopGroup(), new NioEventLoopGroup())
                 .channel(NioServerSocketChannel.class)
                 .handler(new LoggingHandler(LogLevel.INFO))
                 .childHandler(new ChannelInitializer<SocketChannel>() {
                     @Override
                     public void initChannel(SocketChannel socketChannel) throws Exception {
                         socketChannel.pipeline().addLast(new LoggingHandler(LogLevel.INFO));
                         socketChannel.pipeline().addLast(new IntegerCodec());
                     }
                 });

                ChannelFuture f = b.bind(0xAF12).sync();
                f.channel().closeFuture().sync();
            } catch (Exception e) {
                System.out.println(e);
            } finally {
                b.shutdown();
            }
        }
    }

    private static class IntegerCodec extends ByteToMessageCodec<Integer> {
        @Override
        protected void encode(ChannelHandlerContext channelHandlerContext, Integer integer, ByteBuf byteBuf) throws Exception {
            byteBuf.writeInt(integer * 2);
        }

        @Override
        protected Object decode(ChannelHandlerContext channelHandlerContext, ByteBuf byteBuf) throws Exception {
            if (true) {
                throw new Exception("Uh-oh.");
            }

            return byteBuf.readInt() / 2;
        }
    }

}
